public class Solution {
    public int sumOfSubarrayRanges(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int left = nums[0];
        int right = nums[0];
        int sum = nums[0];
        for (int i = 1; i < nums.length; i++) {
            left = Math.min(left, nums[i]);
            right = Math.max(right, nums[i]);
            sum += right - left;
        }
        return sum;
    }
}
```
